-- +goose NO TRANSACTION
-- Dynamic CEL authorization policies. The primary key is a UUIDv7
-- generated by the application; name is the stable permission
-- identifier referenced by routes. Defaults are seeded from
-- internal/core/policy/policy.go on startup; the stored expression
-- always wins over the default. Edited by the admin panel.
-- policy_versions keeps the change history; versions are never deleted.

CREATE TABLE policies (
    id         TEXT PRIMARY KEY,
    name       TEXT NOT NULL UNIQUE,
    expression TEXT NOT NULL,
    updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE TABLE policy_versions (
    id               INTEGER PRIMARY KEY AUTOINCREMENT,
    policy_id        TEXT NOT NULL REFERENCES policies(id) ON DELETE RESTRICT,
    expression       TEXT NOT NULL,
    changed_by       TEXT,
    changed_by_email TEXT,
    origin           TEXT NOT NULL DEFAULT 'system'
                     CHECK (origin IN ('seed', 'admin', 'system')),
    created_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE INDEX idx_policy_versions_policy ON policy_versions (policy_id, id DESC);

-- +goose Down
-- +goose NO TRANSACTION
DROP TABLE policy_versions;
DROP TABLE policies;
